"""Camera-guided stick push controller. No reset or privileged state.
Each CLI invocation continues the same episode; actions and observations are saved.
"""
import sys, os, json, pathlib
import numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=pathlib.Path('/app/output'); RUNS=pathlib.Path('/app/runs')
CAMS=['front','left','right','topview']
def record(res,note,actions=None):
    idx=res.meta.get('calls',res.meta.get('obs_id',0))
    folder=RUNS/f'{idx:04d}_{note}'
    res.save(str(folder))
    (OUT/'latest.json').write_text(json.dumps({'folder':str(folder),'meta':res.meta},indent=2))
    if actions is not None:
        with (OUT/'actions.jsonl').open('a') as f:f.write(json.dumps({'note':note,'actions':actions.tolist()})+'\n')
    print(json.dumps({'folder':str(folder),'tcp':res.meta['proprio']['now'][:4],'mocap':res.meta['proprio']['now'][4:7],'control_steps':res.meta['control_steps'],'time_left':res.meta['time_left_s']}))
    return res

def observe(r,note='observe'):
    return record(r.get_obs(cameras=CAMS,include_depth=True),note)

def send(r,a,note):
    return record(r.submit('ee_delta',a,dt=r.spec()['control_dt'],cameras=CAMS,include_depth=True,video='frames',note=note),note,a)

def move(r,goal,grip,speed=.003,note='move'):
    # Re-estimate hand-to-TCP offset from the robot's measured state.
    o=r.get_obs(cameras=[]); p=np.array(o.meta['proprio']['now']);
    delta=np.array(goal)-p[:3]
    n=max(1,int(np.ceil(np.max(np.abs(delta))/speed)))
    a=np.zeros((n+30,4));a[:n,:3]=delta/(n*.01);a[:,3]=grip
    return send(r,a,note)

if __name__=='__main__':
    r=Robot()
    cmd=sys.argv[1]
    if cmd=='obs':observe(r)
    elif cmd=='move':move(r,list(map(float,sys.argv[2:5])),float(sys.argv[5]),float(sys.argv[6]) if len(sys.argv)>6 else .003,sys.argv[7] if len(sys.argv)>7 else 'move')
    elif cmd=='hold':
        n=int(sys.argv[2]);g=float(sys.argv[3]);a=np.zeros((n,4));a[:,3]=g;send(r,a,'hold')
PY
