import json,numpy as np
from PIL import Image

def data(folder,cam):
 m=json.load(open(folder+'/meta.json')); im=np.array(Image.open(folder+'/last/'+cam+'.jpg'));d=np.load(folder+'/depth_'+cam+'.npy');d=d[-1] if d.ndim==3 else d
 return m,im,d

def back(m,cam,u,v,z):
 K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl']);pc=np.stack([(u-K[0,2])/K[0,0]*z,-(v-K[1,2])/K[1,1]*z,-z],-1)
 return pc@T[:3,:3].T+T[:3,3]

if __name__=='__main__':
 folder=json.load(open('/app/output/latest.json'))['folder']
 for cam in ['topview','front','left','right']:
  m,im,d=data(folder,cam)
  masks={'green':(im[:,:,1]>140)&(im[:,:,1]>im[:,:,0]*1.8)&(im[:,:,1]>im[:,:,2]*1.5),'blue':(im[:,:,2]>80)&(im[:,:,2]>im[:,:,0]*1.4)&(im[:,:,2]>im[:,:,1]*1.2)}
  for name,mask in masks.items():
   v,u=np.where(mask)
   if not len(u):continue
   z=d[v,u].astype(float);w=back(m,cam,u,v,z)
   print(cam,name,'pixel',np.median(u),np.median(v),'depth',np.median(z),'world',np.median(w,0),'range',w.min(0),w.max(0))
